/// <summary>
/// Context: campaigns. Slice: sender-monthly. Fed by MessageQueued.
///
/// RECIPE 5: a MultiStreamProjection over MANY STREAMS OF ONE TYPE.
///
/// This is a different problem from CampaignDashboard's, and conflating the two is easy. There, the events
/// came from two stream types and the difficulty was that some did not carry the key. Here every event is
/// the same type from the same kind of stream — and the difficulty is that a row spans an unbounded number
/// of those streams. One row per (sender, month) collects one event each from hundreds of Message streams.
///
/// TWO THINGS THE MODEL COULD NOT SAY, both of which surface here:
///
/// 1. <c>month</c> IS NOT A FIELD OF ANY EVENT. It comes from the event's own timestamp — metadata, not
///    payload — and the model has no vocabulary for that. It is declared <c>derived="month=MessageQueued"</c>,
///    which reads as "computed from that event" and is the closest true statement available. Reaching the
///    timestamp needs <c>Identity&lt;IEvent&lt;T&gt;&gt;</c> rather than <c>Identity&lt;T&gt;</c>: the
///    envelope carries StreamId, Timestamp and Version, the payload carries none of them.
///
///    **AND THAT TIMESTAMP IS THE APPEND TIME, NOT THE BUSINESS TIME.** Found by running the app: the seed
///    data carries <c>queuedAt = 2026-01-15</c> in every payload, and the row came out keyed <c>2026-08</c>
///    — because <c>IEvent.Timestamp</c> is stamped by Marten when the event is written, and it ignores
///    anything in the payload. For a backfill, an import, or a replay of history that is simply the wrong
///    month, and nothing anywhere says so: it compiles, it passes, and the report is wrong.
///
///    So this recipe answers "messages APPENDED in month M". If the question is "messages SENT in month M",
///    the month has to come from <c>e.Data.QueuedAt</c> — the payload field the model already declares —
///    and the identity rule becomes <c>Identity&lt;MessageQueued&gt;(e =&gt; Key(e.SenderId, e.QueuedAt))</c>
///    with no envelope needed at all. Kept as-is here because demonstrating metadata keying is the point of
///    this file, and because the trap is worth more written down than avoided.
/// 2. THE GENERATOR CANNOT DERIVE THIS IDENTITY, and correctly did not try. It left the rule commented with
///    the reason — MessageQueued carries no <c>month</c> — and left the registration commented too, because
///    a multi-stream projection with no slicing rule is rejected at STARTUP and would take the host down.
///    Both comments were accurate. The judgement they were waiting for is the line below.
///
/// REGISTERED INLINE, where CampaignDashboard is Async — on purpose, so one project shows both costs.
/// Marten's default for multi-stream is Async and its stated reason is write contention on a shared row.
/// That risk is real here and worth naming: two messages from the same sender in the same month DO write
/// the same row. What makes Inline defensible is that the fold is a pure increment and Marten wraps it in
/// the append's transaction. What makes it a decision rather than a default is that under enough
/// concurrency the docs say the increments can stomp each other.
/// </summary>
public sealed record SenderMonthly
{
    public string Id { get; init; } = default!;

    public Guid SenderId { get; init; }

    /// <summary>yyyy-MM, from the event's timestamp. See point 1 above.</summary>
    public string Month { get; init; } = default!;

    /// <summary>Computed from MessageQueued: how many messages this sender sent that month.</summary>
    public int Messages { get; init; }

    /// <summary>Computed from recipients: their total count, summed across those messages.</summary>
    public int Recipients { get; init; }
}

public sealed partial class SenderMonthlyProjection : MultiStreamProjection<SenderMonthly, string>
{
    public SenderMonthlyProjection()
    {
        // IEvent<T>, not T — the month is in the envelope's Timestamp, not in the payload.
        Identity<IEvent<MessageQueued>>(e => Key(e.Data.SenderId, e.Timestamp));
    }

    /// <summary>
    /// The composite key, in one place. A test computing "{sender}:{month}" for itself would be a second
    /// copy of a format string, and the day one of them changes is the day the test stops testing this.
    /// </summary>
    public static string Key(Guid senderId, DateTimeOffset at) => $"{senderId}:{at:yyyy-MM}";

    public SenderMonthly Apply(IEvent<MessageQueued> e, SenderMonthly view) => view with
    {
        Id = Key(e.Data.SenderId, e.Timestamp),
        SenderId = e.Data.SenderId,
        Month = $"{e.Timestamp:yyyy-MM}",
        Messages = view.Messages + 1,
        Recipients = view.Recipients + e.Data.Recipients.Length,
    };
}
